"""Generate a private compile-time namespace without modifying liblc3 sources."""
import pathlib
import re

root = pathlib.Path("ThirdParty/liblc3")
identifiers = set()
for folder in ("include", "src"):
    for source in (root / folder).rglob("*"):
        if source.suffix in (".h", ".c"):
            identifiers.update(re.findall(r"\blc3_[A-Za-z0-9_]+\b", source.read_text()))
assert "lc3_decode" in identifiers and "lc3_setup_decoder" in identifiers
header = root / "g2_namespace.h"
header.write_text(
    "// Generated by G2 LAB: private liblc3 namespace; upstream source is unchanged.\n"
    "#pragma once\n" +
    "".join(f"#define {name} g2_native_{name}\n" for name in sorted(identifiers))
)
